<?php
// usage: php snapshot.php save|restore  (state kept in /tmp/bt/snapshot.json)
$p = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$file = '/tmp/bt/snapshot.json';
if ($argv[1] === 'save') {
    $state = [];
    foreach (['author', 'book', 'customer', 'purchase', 'purchase_line'] as $t) {
        $state[$t] = $p->query("SELECT * FROM $t ORDER BY id")->fetchAll(PDO::FETCH_ASSOC);
    }
    foreach (['author_id_seq', 'book_id_seq', 'customer_id_seq', 'purchase_id_seq', 'purchase_line_id_seq'] as $s) {
        $state['seq'][$s] = $p->query("SELECT last_value, is_called FROM $s")->fetch(PDO::FETCH_ASSOC);
    }
    file_put_contents($file, json_encode($state, JSON_PRETTY_PRINT));
    echo "saved: ", implode(', ', array_map(fn($t) => "$t=" . count($state[$t]), ['author','book','customer','purchase','purchase_line'])), "\n";
} else {
    $state = json_decode(file_get_contents($file), true);
    $p->beginTransaction();
    $p->exec('DELETE FROM purchase_line');
    $p->exec('DELETE FROM purchase');
    foreach ($state['purchase'] as $r) {
        $cols = array_keys($r);
        $p->prepare('INSERT INTO purchase (' . implode(',', $cols) . ') VALUES (' . implode(',', array_map(fn($c) => ':' . $c, $cols)) . ')')->execute($r);
    }
    foreach ($state['purchase_line'] as $r) {
        $cols = array_keys($r);
        $p->prepare('INSERT INTO purchase_line (' . implode(',', $cols) . ') VALUES (' . implode(',', array_map(fn($c) => ':' . $c, $cols)) . ')')->execute($r);
    }
    foreach ($state['book'] as $r) {
        $p->prepare('UPDATE book SET title=:title, author_id=:author_id, published=:published, price_cents=:price_cents, published_at=:published_at, stock=:stock WHERE id=:id')->execute($r);
    }
    $p->commit();
    foreach ($state['seq'] as $s => $v) {
        $p->query(sprintf("SELECT setval('%s', %d, %s)", $s, (int) $v['last_value'], $v['is_called'] ? 'true' : 'false'));
    }
    echo "restored\n";
}
EOF
